CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE app_user (id BIGSERIAL PRIMARY KEY, username TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('CLIENT','ORGANIZER','CHECKER','ADMIN')));
CREATE TABLE venue(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE hall(id BIGSERIAL PRIMARY KEY,venue_id BIGINT NOT NULL REFERENCES venue(id),name TEXT NOT NULL,layout_frozen BOOLEAN NOT NULL DEFAULT false,UNIQUE(venue_id,name));
CREATE TABLE sector(id BIGSERIAL PRIMARY KEY,hall_id BIGINT NOT NULL REFERENCES hall(id),name TEXT NOT NULL,category TEXT NOT NULL,UNIQUE(hall_id,name));
CREATE TABLE seat(id BIGSERIAL PRIMARY KEY,hall_id BIGINT NOT NULL REFERENCES hall(id),sector_id BIGINT NOT NULL REFERENCES sector(id),row_label TEXT NOT NULL,number INT NOT NULL,x INT NOT NULL,y INT NOT NULL,accessible BOOLEAN NOT NULL DEFAULT false,UNIQUE(hall_id,row_label,number));
CREATE TABLE season(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,starts_on DATE NOT NULL,ends_on DATE NOT NULL);
CREATE TABLE event(id BIGSERIAL PRIMARY KEY,hall_id BIGINT NOT NULL REFERENCES hall(id),season_id BIGINT REFERENCES season(id),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,occupied_start TIMESTAMPTZ NOT NULL,occupied_end TIMESTAMPTZ NOT NULL,setup_minutes INT NOT NULL DEFAULT 60,teardown_minutes INT NOT NULL DEFAULT 30,priority_opens_at TIMESTAMPTZ,public_opens_at TIMESTAMPTZ NOT NULL,status TEXT NOT NULL DEFAULT 'PUBLISHED' CHECK(status IN ('PUBLISHED','CANCELLED')),CHECK(ends_at>starts_at),CHECK(setup_minutes>=0 AND teardown_minutes>=0));
ALTER TABLE event ADD CONSTRAINT hall_occupied_no_overlap EXCLUDE USING gist (hall_id WITH =, tstzrange(occupied_start,occupied_end,'[)') WITH &&) WHERE (status='PUBLISHED');
CREATE TABLE tariff(id BIGSERIAL PRIMARY KEY,event_id BIGINT NOT NULL REFERENCES event(id),category TEXT NOT NULL,price NUMERIC(12,2) NOT NULL CHECK(price>=0),UNIQUE(event_id,category));
CREATE TABLE event_seat(id BIGSERIAL PRIMARY KEY,event_id BIGINT NOT NULL REFERENCES event(id),seat_id BIGINT NOT NULL REFERENCES seat(id),price NUMERIC(12,2) NOT NULL CHECK(price>=0),status TEXT NOT NULL DEFAULT 'AVAILABLE' CHECK(status IN ('AVAILABLE','SOLD','PASS')),pass_owner BIGINT REFERENCES app_user(id),UNIQUE(event_id,seat_id));
CREATE TABLE season_pass(id BIGSERIAL PRIMARY KEY,season_id BIGINT NOT NULL REFERENCES season(id),owner_id BIGINT NOT NULL REFERENCES app_user(id),type TEXT NOT NULL CHECK(type IN ('FIXED','PRIORITY')),seat_id BIGINT REFERENCES seat(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK ((type='FIXED' AND seat_id IS NOT NULL) OR (type='PRIORITY' AND seat_id IS NULL)),UNIQUE(season_id,seat_id));
CREATE TABLE season_seat_assignment(id BIGSERIAL PRIMARY KEY,pass_id BIGINT NOT NULL REFERENCES season_pass(id),event_id BIGINT NOT NULL REFERENCES event(id),event_seat_id BIGINT NOT NULL REFERENCES event_seat(id),UNIQUE(event_seat_id),UNIQUE(pass_id,event_id));
CREATE TABLE seat_hold(id BIGSERIAL PRIMARY KEY,event_seat_id BIGINT NOT NULL REFERENCES event_seat(id),owner_id BIGINT NOT NULL REFERENCES app_user(id),token UUID NOT NULL,expires_at TIMESTAMPTZ NOT NULL,status TEXT NOT NULL CHECK(status IN ('ACTIVE','CONSUMED','EXPIRED')));
CREATE UNIQUE INDEX one_active_hold ON seat_hold(event_seat_id) WHERE status='ACTIVE';
CREATE INDEX hold_expiry ON seat_hold(expires_at) WHERE status='ACTIVE';
CREATE TABLE customer_order(id BIGSERIAL PRIMARY KEY,owner_id BIGINT NOT NULL REFERENCES app_user(id),event_id BIGINT NOT NULL REFERENCES event(id),hold_token UUID NOT NULL UNIQUE,idempotency_key TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('PAID','DECLINED')),total NUMERIC(12,2) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(owner_id,idempotency_key));
CREATE TABLE order_item(id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES customer_order(id),event_seat_id BIGINT NOT NULL REFERENCES event_seat(id),price NUMERIC(12,2) NOT NULL,UNIQUE(event_seat_id));
CREATE TABLE payment_attempt(id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES customer_order(id),result TEXT NOT NULL,external_key TEXT NOT NULL UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ticket(id BIGSERIAL PRIMARY KEY,order_item_id BIGINT UNIQUE REFERENCES order_item(id),event_seat_id BIGINT NOT NULL REFERENCES event_seat(id),event_id BIGINT NOT NULL REFERENCES event(id),owner_id BIGINT NOT NULL REFERENCES app_user(id),code UUID NOT NULL UNIQUE,status TEXT NOT NULL CHECK(status IN ('ACTIVE','USED','CANCELLED')),UNIQUE(event_seat_id));
CREATE TABLE ticket_check_in(id BIGSERIAL PRIMARY KEY,ticket_id BIGINT NOT NULL UNIQUE REFERENCES ticket(id),checked_by BIGINT NOT NULL REFERENCES app_user(id),checked_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_entry(id BIGSERIAL PRIMARY KEY,actor_id BIGINT REFERENCES app_user(id),action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX event_schedule ON event(hall_id,starts_at); CREATE INDEX event_seat_event ON event_seat(event_id,status); CREATE INDEX ticket_owner ON ticket(owner_id);
